usage:
@State private var cards = Card.samples

HugsySwipeDeck(items: $cards) { card, progress in
  CardView(card)
    .overlay { Stamp(progress: progress) }
}
.frame(height: 520)

@State private var phase = HugsyCapsulePhase.compact

HugsyMorphingCapsule(phase: $phase) { phase in
  switch phase {
  case .compact: CompactTimer()
  case .alert: Label("Saved", systemImage: "checkmark")
  case .expanded: PlayerControls()
  }
}

@State private var selected: Story.ID?

HugsyExpandingCards(items: stories, selection: $selected) { story, expanded in
  VStack(alignment: .leading, spacing: 16) {
    Text(story.title).font(.largeTitle.bold())
    if expanded { Text(story.description) }
  }
  .padding(28)
  .frame(maxWidth: .infinity, maxHeight: .infinity)
  .background(story.color.gradient)
}

@State private var expanded = false

HugsyRadialMenu(actions: [
  .init(id: "photo", title: "Add photo", symbol: "camera") { addPhoto() },
  .init(id: "note", title: "New note", symbol: "square.and.pencil") { newNote() },
  .init(id: "link", title: "Save link", symbol: "link") { saveLink() }
], isExpanded: $expanded)

uikitUsage:
let menu = HugsyRadialMenuViewController(actions: [
  .init(id: "photo", title: "Add photo", symbol: "camera") { addPhoto() },
  .init(id: "note", title: "New note", symbol: "square.and.pencil") { newNote() }
])
menu.didChangeExpansion = { expanded in
  print(expanded)
}
addChild(menu)
view.addSubview(menu.view)
menu.didMove(toParent: self)

